/**
 * Typed errors bridged to native Swift Error enums.
 */
public enum StitcherError {

    
    
    case InvalidDirectory(path: String
    )
    case IoError(message: String
    )
    case NoClipsFound(hourPath: String
    )
    case Mp4MergeFailed(reason: String
    )
    case FallbackRemuxFailed(reason: String
    )
    case JobNotFound(jobId: String
    )
    case Cancelled
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeStitcherError: FfiConverterRustBuffer {
    typealias SwiftType = StitcherError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> StitcherError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidDirectory(
            path: try FfiConverterString.read(from: &buf)
            )
        case 2: return .IoError(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NoClipsFound(
            hourPath: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Mp4MergeFailed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .FallbackRemuxFailed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .JobNotFound(
            jobId: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: StitcherError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidDirectory(path):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .IoError(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NoClipsFound(hourPath):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(hourPath, into: &buf)
            
        
        case let .Mp4MergeFailed(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .FallbackRemuxFailed(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .JobNotFound(jobId):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(jobId, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(7))
        
        }
    }
}


